package dev.cardstashy.nativeplay

import com.google.gson.JsonObject
import com.google.gson.JsonParser
import dev.cardstashy.nativeplay.foil.PtcgFoil
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File
import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.util.zip.GZIPInputStream
import kotlin.math.abs

/** The app classifies, resolves and measures a Pokémon card exactly like the site (vectors and golden maps generated by the site's own modules at 6ceede8c). */
class PtcgFoilTest {
    private val masks by lazy { PtcgFoil.Masks.parse(File("src/main/res/raw/ptcg_masks.json").readText()) }
    private val vectors by lazy { JsonParser.parseString(javaClass.getResourceAsStream("/foil/ptcg-vectors.json")!!.bufferedReader().readText()).asJsonObject }
    private fun JsonObject.str(k: String): String? = this[k]?.takeIf { !it.isJsonNull }?.asString

    @Test fun framesMatchTheSite() {
        var n = 0
        for (e in vectors.getAsJsonArray("frames")) {
            val v = e.asJsonObject
            assertEquals(v.toString(), v.str("frame") ?: "", PtcgFoil.frame(v.str("set") ?: "", v.str("category"), v.str("stage"), v.str("name"), v.str("id") ?: "", masks.anniversary.keys)); n++
        }
        assertEquals(193, n)
    }

    @Test fun printingsResolveLikeTheSite() {
        for (e in vectors.getAsJsonArray("fixtures")) {
            val f = e.asJsonObject; val c = f.getAsJsonObject("card"); val set = c.getAsJsonObject("set")
            val image = c.str("image")
            val card = PtcgFoil.Card(c.str("id")!!, set.str("id") ?: "", c.str("name") ?: "", c.str("category") ?: "Pokemon", c.str("stage"), c.str("rarity"), c.str("localId"),
                set.str("number"), image, image?.let { "$it/high.webp" })
            assertEquals(card.id, f.str("frame") ?: "", PtcgFoil.frame(card.setId, card.category, card.stage, card.name, card.id, masks.anniversary.keys))
            val details = c.getAsJsonArray("variants_detailed")
            f.getAsJsonArray("choices").forEachIndexed { i, ce ->
                val ch = ce.asJsonObject; val key = ch.str("key")!!
                val v = if (details != null && i < details.size()) {
                    val d = details[i].asJsonObject
                    PtcgFoil.Variant(key, finish = mapOf("normal" to "normal", "holo" to "holofoil", "reverse" to "reverse-holofoil")[d.str("type")], foil = d.str("foil"), size = d.str("size"), subtype = d.str("subtype"),
                        stamps = d.getAsJsonArray("stamp")?.map { it.asString } ?: emptyList())
                } else PtcgFoil.Variant(key)
                val p = PtcgFoil.resolve(card, v, masks)
                val tag = "${card.id} $key"
                assertEquals(tag, ch.str("effect"), p.effect); assertEquals(tag, ch.str("mask"), p.mask); assertEquals(tag, ch.str("treatment"), p.treatment)
                assertEquals(tag, ch.str("coverage"), p.coverage); assertEquals(tag, ch.str("pattern"), p.pattern); assertEquals(tag, ch.str("status"), p.status)
            }
        }
    }

    private fun golden(name: String, treatment: String, mask: String, window: Boolean) {
        val raw = GZIPInputStream(javaClass.getResourceAsStream("/foil/$name-golden.bin.gz")!!).readBytes()
        val bb = ByteBuffer.wrap(raw).order(ByteOrder.LITTLE_ENDIAN); val W = bb.int; val H = bb.int; val N = W * H
        var o = 8
        val rgba = raw.copyOfRange(o, o + N * 4); o += N * 4
        val mask0 = raw.copyOfRange(o, o + N * 4); o += N * 4
        val relief = raw.copyOfRange(o, o + N * 4)
        val argb = IntArray(N) { i -> (255 shl 24) or ((rgba[i * 4].toInt() and 255) shl 16) or ((rgba[i * 4 + 1].toInt() and 255) shl 8) or (rgba[i * 4 + 2].toInt() and 255) }
        val shape = masks.shape(mask)!!
        val m = PtcgFoil.analyze(argb, W, H, PtcgFoil.RECIPES[treatment]!!, shape, shape, null, window)
        fun u(b: Byte) = b.toInt() and 255
        val off = IntArray(5); var worst = 0; var edge = 0
        for (i in 0 until N) {
            val k = i * 4
            val pairs = listOf(u(m.mask[k]) to u(mask0[k]), u(m.mask[k + 1]) to u(mask0[k + 1]), u(m.relief[k]) to u(relief[k]), u(m.relief[k + 1]) to u(relief[k + 1]), u(m.relief[k + 2]) to u(relief[k + 2]))
            // Stroke direction (relief G/B) is noise where the brushwork tensor is weak (site strength in relief A): only compare it where the stroke is real.
            val stroke = u(relief[k + 3]) > 24
            pairs.forEachIndexed { c, (a, b) -> val d = abs(a - b); if (c >= 3 && !stroke) return@forEachIndexed; worst = maxOf(worst, d); if (d > 2) off[c]++ }
            // Coverage: the site fills the clip on a canvas; the app rasterises it itself, so only anti-aliased edge pixels may differ, never a shifted mask.
            if (abs(u(m.mask[k + 2]) - u(mask0[k + 3])) > 48) edge++
        }
        off.forEachIndexed { c, n -> assertTrue("$name channel $c: $n of $N pixels differ by more than 2 (worst $worst)", n < N / 1000) }
        assertTrue("$name coverage: $edge of $N pixels off", edge < N / 1000)
    }
    @Test fun reverseSurroundMeasuresLikeTheSite() = golden("mantine-reverse", "ptcg-reverse", "pk-swsh-surround", false)
    @Test fun holoWindowMeasuresLikeTheSite() = golden("zekrom-holo", "ptcg-vsheen", "pk-cel-art", true)

    @Test fun sheetsFollowTheSite() {
        assertEquals("ptcg-vsheen", PtcgFoil.foilEffect("holofoil", era = "pk-swsh"))
        assertEquals("ptcg-prismatic-masterball", PtcgFoil.foilEffect("reverse-holofoil", foil = "Master Ball", set = "sv08.5"))
        assertEquals("ptcg-gold", PtcgFoil.foilEffect("holofoil", rarity = "Hyper rare", fullArt = true, gold = true, set = "sv01"))
        assertEquals("ptcg-rc-dots", PtcgFoil.foilEffect("holofoil", number = "RC12"))
        assertEquals("ptcg-emblem-reverse", PtcgFoil.foilEffect("reverse-holofoil", set = "bw7"))
    }
}
